import argparse
import json

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    payload = json.loads(args.payload)
    path = payload['path']

    user_last_actions = {}

    with open(path, 'r') as f:
        for line in f:
            if line.strip():
                event = json.loads(line)
                user = event['user']
                ts = event['ts']
                action = event['action']

                if user not in user_last_actions or ts > user_last_actions[user]['ts']:
                    user_last_actions[user] = {'ts': ts, 'action': action}

    logout_count = sum(1 for info in user_last_actions.values() if info['action'] == 'logout')
    print(logout_count)

if __name__ == "__main__":
    main()

