import argparse
import json
def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    payload = json.loads(args.payload)
    path = payload['path']

    user_events = {}

    with open(path, 'r') as f:
        for line in f:
            if not line.strip():
                continue
            event = json.loads(line)
            user = event.get('user')
            action = event.get('action')
            ts = event.get('ts')
            if user is None or action is None or ts is None:
                continue
            if user not in user_events:
                user_events[user] = []
            user_events[user].append((ts, action))

    logout_count = 0
    for events in user_events.values():
        if not events:
            continue
        events.sort(key=lambda x: x[0])
        last_action = events[-1][1]
        if last_action == 'logout':
            logout_count += 1

    print(logout_count)

if __name__ == '__main__':
    main()
